base='https://raw.githubusercontent.com/openmm/openmm/53770948682c40bd460b39830d4e0f0fd3a4b868/'
urls={'pdb':base+'examples/5dfr_solv-cube_equil.pdb','benchmark':base+'examples/benchmark.py','nvidia':'https://developer.nvidia.com/blog/maximizing-openmm-molecular-dynamics-throughput-with-nvidia-multi-process-service/','openmm':'https://pypi.org/pypi/openmm/8.2.0/json','cuda':'https://pypi.org/pypi/OpenMM-CUDA-12/8.2.0/json','tag':'https://api.github.com/repos/openmm/openmm/git/ref/tags/8.2.0','properties':'https://docs.openmm.org/8.2.0/userguide/library/04_platform_specifics.html','amber':base+'wrappers/python/openmm/app/data/amber99sb.xml','water':base+'wrappers/python/openmm/app/data/tip3p.xml'}
def fetch(item):
