  elif k=='nvidia':
   import re
   s=re.sub('<["'^>]+>'"',' ',s);s=re.sub(r'\\s+',' ',s)
   result['excerpts']=[s[max(0,m.start()-100):m.end()+220] for m in re.finditer('more than double|15.{0,10}25|5 microseconds|benchmark.py|200 /|200/|Jun 04',s)]
